// Preview only. Research rows never become public listings here.
const rows = $input.all().map(item => item.json);
const byId = new Map();
const statuses = new Set(['Unreviewed','Approved','Rejected','Excluded']);
for (const row of rows) {
  if (!row.candidate_id || !statuses.has(row.approval_status)) throw new Error('Invalid review row');
  if (byId.has(row.candidate_id)) throw new Error('Duplicate candidate_id; resolve before digest');
  byId.set(row.candidate_id,row);
}
const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
const part = type => parts.find(p=>p.type===type).value;
const today = part('year')+'-'+part('month')+'-'+part('day');
const pending = [...byId.values()].filter(r=>r.approval_status==='Unreviewed');
const due = pending.filter(r=>r.owner && /^\d{4}-\d{2}-\d{2}$/.test(r.follow_up_at||'') && r.follow_up_at<=today && String(r.last_notified_at||'').slice(0,10)!==today);
const regions={};
for(const row of pending) regions[row.region]=(regions[row.region]||0)+1;
const lines = [
  'NaviiGo internal pilot review / '+today,
  '',
  pending.length+' research references await review.',
  pending.filter(r=>!r.owner).length+' have no assigned owner.',
  due.length+' assigned review follow-ups are due.',
  [...byId.values()].filter(r=>r.approval_status==='Excluded').length+' excluded; never included in follow-up tasks.',
  '',
  'Pending by region:',
  ...Object.entries(regions).map(([region,n])=>' - '+region+': '+n),
  '',
  'Due review tasks:',
  ...(due.length ? due.slice(0,50).map(r=>' - '+r.place_name+' / '+r.owner+' / '+r.follow_up_at+' / '+r.candidate_id) : ['None. Assign owners and dates in the review sheet.']),
  '',
  'These are research references, not verified partners. The separate partner approval workbook is still pending.',
  'This preview sends no messages and does not change approvals.'
];
return [{json:{preview_only:true,date:today,subject:'[NaviiGo] Pilot review digest / '+today,
  body_text:lines.join('\n'),pending_count:pending.length,due_count:due.length,
  due_candidate_ids:due.map(r=>r.candidate_id),
  digest_key:today+':'+due.map(r=>r.candidate_id).sort().join('|')}}];
